using Asp.Versioning;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Servicio.RetazoMarket.Api.Extensions;using Servicio.RetazoMarket.Api.Models.Common;using Servicio.RetazoMarket.Business.DTOs.Imagen;using Servicio.RetazoMarket.Business.Exceptions;using Servicio.RetazoMarket.Business.Interfaces;
namespace Servicio.RetazoMarket.Api.Controllers.V1.Internal.Catalogo;
[ApiController][ApiVersion("1.0")][Authorize(Policy=AuthorizationExtensions.AdministradorPolicy)][Route("api/v{version:apiVersion}/internal/imagenes")][ProducesResponseType(typeof(ApiErrorResponse),400)][ProducesResponseType(typeof(ApiErrorResponse),401)][ProducesResponseType(typeof(ApiErrorResponse),403)][ProducesResponseType(typeof(ApiErrorResponse),404)]
public class ImagenesController:ControllerBase{private readonly IImagenService _s;public ImagenesController(IImagenService s)=>_s=s;
[HttpGet("{id:int}")]public async Task<IActionResult> PorId(int id,CancellationToken ct)=>Ok(ApiResponse<ImagenResponse>.Ok(await _s.ObtenerPorIdAsync(id,ct)??throw new NotFoundException("La imagen no existe.")));
[HttpGet("producto/{id:int}")]public async Task<IActionResult> PorProducto(int id,CancellationToken ct)=>Ok(ApiResponse<IReadOnlyList<ImagenResponse>>.Ok(await _s.ObtenerPorProductoAsync(id,ct)));
[HttpPost]public async Task<IActionResult> Crear([FromBody]CrearImagenRequest r,CancellationToken ct){var x=await _s.CrearAsync(r,ct);return CreatedAtAction(nameof(PorId),new{version="1.0",id=x.id_imagen},ApiResponse<ImagenResponse>.Ok(x,"Imagen creada exitosamente."));}
[HttpPut("{id:int}")]public async Task<IActionResult> Actualizar(int id,[FromBody]ActualizarImagenRequest r,CancellationToken ct){r.id_imagen=id;return Ok(ApiResponse<ImagenResponse>.Ok(await _s.ActualizarAsync(r,ct)??throw new NotFoundException("La imagen no existe.")));}}
